                post_hook={
                    "sql": "create or replace table maplemonk.saadaa_returns_consolidated as select s.order_name as reference_code ,s.Line_Item_ID as saleorderitemcode ,s.order_id ,s.order_status ,cast(DATETIME(TIMESTAMP(order_timestamp)) as date) AS Order_Date ,UPPER(s.marketplace) as marketplace ,UPPER(coalesce(GA4.CHANNEL,s.FINAL_UTM_CHANNEL)) as marketing_channel ,UPPER(coalesce(GA4.final_source,s.FINAL_UTM_SOURCE)) as source ,UPPER(s.product_name) as product_name ,coalesce(r.returned_sku,s.sku) as sku ,upper(s.category) as product_category ,upper(s.PRODUCT_SUB_CATEGORY) as product_sub_category ,s.quantity as order_quantity ,s.city ,s.state ,s.pincode ,s.courier as shipping_courier ,s.awb ,s.name as customer_name ,s.email as customer_email ,r.return_request_number ,datetime(timestamp(r.request_requested_at)) as return_requested_date ,datetime(r.return_approved_at) as return_approved_date ,datetime(r.refunded_at) as return_refunded_at ,cast(r.return_date as datetime) as return_date ,r.return_approval_status ,r.return_request_type ,case when r.return_request_type = \'return\' then r.return_request_type when r.return_request_type = \'exchange\' then r.return_request_type when (lower(c.shipping_status) like \'%rto%\' or lower(c.shipping_status) like \'delivered to origin\') then \'RTO\' when (lower(coalesce(c.shipping_status,s.shipping_status)) like \'%lost%\') then \'lost\' else null end as return_type ,(case when r.return_flag is not null then r.return_flag else 0 end) as return_flag ,r.returned_quantity as TOTAL_RETURNED_QUANTITY ,r.return_reason ,s.payment_mode ,s.total_sales ,r.returned_product_name ,r.returned_product_variant ,r.returned_sku ,cast(r.returned_product_price as float64) as returned_product_price ,(case when return_flag = 1 then s.tax else 0 end) as TOTAL_RETURN_TAX ,(cast(r.returned_product_price as float64) - (case when return_flag = 1 then s.tax else 0 end)) as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.return_line_item_id as returned_item_saleorderitemcode ,r.exchange_product_name ,r.exchange_product_variant ,r.exchange_sku ,r.exchange_product_total_price ,r.exchange_status ,c.order_status as oms_order_status from saadaa-wh.maplemonk.saadaa_shopify_fact_items s left join saadaa-wh.maplemonk.saadaa_returnsprime_consolidated r on s.order_name = r.order_name and s.line_item_id = r.order_item_id left join (select transactionid, final_source, channel from maplemonk.SAADAA_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) =1 ) GA4 on replace(s.order_name,\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from maplemonk.SAADAA_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(s.order_name,\'#\',\'\') = replace(c.reference_code,\'#\',\'\') and replace(s.LINE_ITEM_ID,\'`\',\'\')=replace(c.Marketplace_LineItem_ID,\'`\',\'\') where abs(s.total_sales) > 10 AND (not (lower(s.name) like \'%market%\' or lower(s.name) like \'%inf%\') or lower(s.name) is null) AND (c.warehouse_name IS NULL OR (not(upper(c.warehouse_name) = \'SAADAA - MATERIAL WAREHOUSE OLD\' or upper(c.warehouse_name) like \'%INFLUENCER%\'))) AND (lower(s.name) is null or not(lower(s.name) like \'%photoshoot%\')) AND not(upper(s.order_name) like \'%STN%\') UNION ALL select e.reference_code ,e.Marketplace_LineItem_ID AS SALEORDERITEMCODE ,e.ORDER_ID ,Upper(e.order_status) as order_status ,cast(e.ORDER_DATE as datetime) AS Order_Date ,UPPER(e.marketplace) AS marketplace ,UPPER(e.marketplace) AS MARKETING_CHANNEL ,UPPER(e.marketplace) AS SOURCE ,UPPER(e.PRODUCTNAME) AS PRODUCT_NAME ,e.SKU ,UPPER(e.mapped_category) AS product_category ,UPPER(e.mapped_sub_category) AS product_sub_category ,e.suborder_quantity as order_quantity ,UPPER(e.CITY) AS City ,UPPER(e.STATE) AS State ,e.pincode ,UPPER(e.COURIER) AS Shipping_Courier ,e.awb ,e.customer_name AS NAME ,e.email AS EMAIL ,cast(null as string) as return_request_number ,cast(null as datetime) as return_requested_date ,cast(null as datetime) as return_approved_date ,cast(null as datetime) as return_refunded_at ,cast(r.return_date as datetime) as return_date ,case when coalesce((case when return_date is not null then 1 end),e.is_refund) = 1 then \'Approved\' else null end as return_approval_status ,case when coalesce((case when return_date is not null then 1 end),e.is_refund) = 1 then \'return\' else null end as return_request_type ,case when lower(r.return_reason) like \'%lost%\' then \'lost\' when lower(r.return_reason) like \'%exchange%\' then \'exchange\' when (lower(r.return_reason) like \'%rto%\' or lower(r.return_reason) like \'%not serviceable%\') then \'RTO\' when r.return_reason is not null then \'return\' else null end as return_type ,coalesce((case when return_date is not null then 1 end),e.is_refund) as return_flag ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,r.return_reason ,e.Payment_mode ,e.selling_price ,r.PRODUCTNAME as returned_product_name ,r.RETURNED_PRODUCT_SIZE as returned_product_variant ,r.SKU as returned_sku ,r.TOTAL_RETURN_AMOUNT ,case when e.is_refund = 1 then e.tax else 0 end as TOTAL_RETURN_TAX ,r.RETURN_AMOUNT_WITHOUT_TAX as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.suborder_num as returned_item_saleorderitemcode ,case when lower(r.return_reason) like \'%exchange%\'then r.PRODUCTNAME end as exchange_product_name ,case when lower(r.return_reason) like \'%exchange%\'then r.RETURNED_PRODUCT_SIZE end as exchange_product_variant ,case when lower(r.return_reason) like \'%exchange%\'then r.sku end as exchange_sku ,case when lower(r.return_reason) like \'%exchange%\'then e.selling_price end as exchange_product_total_price ,cast(null as string) as exchange_status ,e.order_status as oms_order_status from maplemonk.saadaa_easyecom_fact_items e left join maplemonk.SAADAA_easyecom_returns_intermediate r on e.reference_code = r.reference_code and e.marketplace_lineitem_id = r.suborder_num where not(lower(e.marketplace) like \'%shopify%\' or lower(e.marketplace) like \'%amazon%\') AND abs(e.selling_price) > 10 AND (not (lower(e.customer_name) like \'%market%\' or lower(e.customer_name) like \'%inf%\') or lower(e.customer_name) is null) AND (e.warehouse_name IS NULL OR (not(upper(e.warehouse_name) = \'SAADAA - MATERIAL WAREHOUSE OLD\' or upper(e.warehouse_name) like \'%INFLUENCER%\'))) AND (lower(e.customer_name) is null or not(lower(e.customer_name) like \'%photoshoot%\')) AND not(upper(e.reference_code) like \'%STN%\') UNION ALL select a.order_id as reference_code ,concat(a.order_id,\'-\',a.product_id) as saleorderitemcode ,a.order_id ,upper(a.order_status) as order_status ,cast(a.order_timestamp as date) as order_date ,\'AMAZON\' AS marketplace ,\'AMAZON\' AS marketing_CHANNEL ,\'AMAZON\' AS SOURCE ,a.product_name ,a.sku ,a.product_category ,a.product_sub_category ,a.quantity as order_quantity ,a.city ,a.state ,e.pincode ,e.courier as shipping_courier ,e.awb ,a.name as customer_name ,coalesce(e.email,a.email) as customer_email ,cast(null as string) as return_request_number ,cast(null as datetime) as return_requested_date ,cast(null as datetime) as return_approved_date ,cast(null as datetime) as return_refunded_at ,cast(r.return_date as datetime) as return_date ,case when coalesce((case when return_date is not null then 1 end),a.is_refund) = 1 then \'Approved\' else null end as return_approval_status ,case when coalesce((case when return_date is not null then 1 end),a.is_refund) = 1 then \'return\' else null end as return_request_type ,case when lower(r.return_reason) like \'%lost%\' then \'lost\' when lower(r.return_reason) like \'%exchange%\' then \'exchange\' when r.return_reason in (\'RTO\',\'not serviceable\') then \'RTO\' when r.return_reason is not null then \'return\' else null end as return_type ,coalesce((case when return_date is not null then 1 else null end),a.is_refund) as return_flag ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,r.return_reason ,e.Payment_mode ,a.TOTAL_SALES ,r.PRODUCTNAME as returned_product_name ,r.RETURNED_PRODUCT_SIZE as returned_product_variant ,r.SKU as returned_sku ,r.TOTAL_RETURN_AMOUNT as returned_product_price ,case when a.is_refund = 1 then a.tax else 0 end as TOTAL_RETURN_TAX ,r.RETURN_AMOUNT_WITHOUT_TAX as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.suborder_num as returned_item_saleorderitemcode ,case when lower(r.return_reason) like \'%exchange%\' then r.PRODUCTNAME end as exchange_product_name ,case when lower(r.return_reason) like \'%exchange%\' then r.RETURNED_PRODUCT_SIZE end as exchange_product_variant ,case when lower(r.return_reason) like \'%exchange%\' then r.sku end as exchange_sku ,case when lower(r.return_reason) like \'%exchange%\' then e.selling_price end as exchange_product_total_price ,cast(null as string) as exchange_status ,e.order_status as oms_order_status from maplemonk.saadaa_amazon_fact_items a left join ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM maplemonk.SAADAA_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%amazon%\' )e on a.ordeR_id = e.reference_code and a.sku = e.sku left join ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw1 FROM maplemonk.SAADAA_easyecom_returns_intermediate ) z1 WHERE z1.rw1 = 1 AND LOWER(marketplace) LIKE \'%amazon%\' ) r on lower(trim(a.ordeR_id)) = lower(trim(r.reference_code)) and lower(trim(a.commonsku)) = lower(trim(r.sku)) where abs(a.TOTAL_SALES) > 10 AND (not (lower(a.name) like \'%market%\' or lower(a.name) like \'%inf%\') or lower(a.name) is null) AND (e.warehouse_name IS NULL OR (not(upper(e.warehouse_name) = \'SAADAA - MATERIAL WAREHOUSE OLD\' or upper(e.warehouse_name) like \'%INFLUENCER%\'))) AND (lower(a.name) is null or not(lower(a.name) like \'%photoshoot%\')) AND not(upper(a.order_id) like \'%STN%\') ; CREATE OR REPLACE TABLE saadaa-wh.maplemonk.saadaa_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(order_Date, MONTH) as month_first_date, date(order_date) as order_date, marketplace, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 and return_request_type = \'return\') THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'return\') then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'return\') then TOTAL_RETURNED_QUANTITY else 0 end) as total_returned_quantity_for_orders_of_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 and return_request_type = \'exchange\') THEN reference_code END) AS total_exchange_orders_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'exchange\') then 1 else 0 end) as total_exchange_items_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'exchange\') then TOTAL_RETURNED_QUANTITY else 0 end) as total_exchange_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(total_sales) as total_sales FROM saadaa-wh.maplemonk.saadaa_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as returned_quantity_received_in_month, sum(total_sales) as total_returned_sales FROM saadaa-wh.maplemonk.saadaa_returns_consolidated WHERE return_flag = 1 and return_request_type = \'return\' GROUP BY return_month,return_date,marketplace ), exchanges as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, COUNT(*) as total_exchange_items_received_in_month, count(distinct reference_code) as exchange_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as exchange_quantity_received_in_month, FROM saadaa-wh.maplemonk.saadaa_returns_consolidated WHERE return_flag = 1 and return_request_type = \'exchange\' GROUP BY return_month,return_date,marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, o.total_exchange_orders_for_orders_of_month, o.total_exchange_items_for_orders_of_month, o.total_exchange_quantity_for_orders_of_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month, e.total_exchange_items_received_in_month, e.exchange_orders_received_in_month, e.exchange_quantity_received_in_month, from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace LEFT JOIN exchanges e ON e.return_date = o.order_date and e.marketplace = o.marketplace order by order_date desc;",
